import {esc} from './ui.js';
const flows=[
 ['source code','the compiler','your program','main.rs','types + ownership','native binary'],
 ['your values','the expression','the result','bindings + types','evaluate + branch','typed output'],
 ['the owner','the allocation','the borrow','stack binding','owned data','temporary access'],
 ['your domain','the type','the match','real-world states','structs + enums','exhaustive paths'],
 ['the input','the operation','the outcome','collections + data','transform + validate','Some / None · Ok / Err'],
 ['the interface','the contract','the implementation','trait + lifetime','bounds + relationships','concrete behavior'],
 ['the values','the adapter','the consumer','owned or borrowed','lazy transformations','collect · sum · fold'],
 ['your change','the checks','the feedback','code + tests','fmt · clippy · test','confidence to change'],
 ['the work','the coordination','the result','tasks + messages','ownership + synchronization','bounded concurrency'],
 ['the boundary','the invariant','the safe API','memory + foreign code','explicit obligations','reviewed abstraction'],
 ['the request','the service','the response','validated input','state + I/O + errors','observable behavior'],
 ['the problem','the implementation','the delivery','requirements + cases','build + test + iterate','release + operate']
];
export function lessonExperiment(l,s){const step=l.steps.indexOf(s),flow=flows[l.moduleIndex]||flows[0];return{flow,step,focus:['Build','Types','Memory','Types','Data','Contracts','Values','Quality','Tasks','Safety','Services','Projects'][l.moduleIndex]||'Rust',stage:['source','check','build','run','recap'].includes(s.phase)?({source:'Explore',check:'Validate',build:'Build',run:'Observe',recap:'Review'}[s.phase]):'Explore'};}
function platform(x,color){return `<path d="M${x-85} 245l85-48 85 48v10l-85 48-85-48z" fill="var(--line)" stroke="var(--ink)" stroke-width="1.4"/><path d="M${x-85} 245l85-48 85 48-85 48z" fill="${color}" stroke="var(--ink)" stroke-width="1.4"/>`}
export function scene(l,s,x){const active=x.step>0,out=x.step>2,flow=x.flow;const code=s.code.split('\n').filter(Boolean).slice(0,4);const memory=l.moduleIndex===2;return `<svg class="diagram rust-diagram" viewBox="0 0 850 370" role="img" aria-label="Conceptual flow from ${esc(flow[0])}, through ${esc(flow[1])}, to ${esc(flow[2])}"><defs><pattern id="iso-grid" width="48" height="28" patternUnits="userSpaceOnUse"><path d="M0 0L48 28M48 0L0 28" stroke="var(--line)" stroke-width="1" opacity=".5"/></pattern><radialGradient id="fade"><stop offset="0" stop-color="white"/><stop offset="1" stop-color="black"/></radialGradient><mask id="grid-mask"><ellipse cx="425" cy="190" rx="425" ry="200" fill="url(#fade)"/></mask></defs><rect width="850" height="370" fill="url(#iso-grid)" mask="url(#grid-mask)"/><path d="M230 238L310 285L425 218M480 238L565 285L690 218" class="wire ${active?'active':''}"/>${platform(165,'var(--orange)')}${platform(425,'var(--violet)')}${platform(690,'var(--green)')}
<g class="node" transform="translate(87,102)"><path d="M7 10h155v140H7z" fill="var(--line)" stroke="var(--ink)"/><rect width="155" height="140" rx="6" fill="var(--sheet)" stroke="var(--ink)" stroke-width="1.5"/><path d="M1 6q0-5 5-5h143q5 0 5 5v21H1Z" fill="var(--orange)"/><circle cx="12" cy="14" r="3" fill="var(--rust)"/><text x="24" y="18" font-size="10">${memory?'the binding':'source.rs'}</text>${memory?`<text x="14" y="55" font-size="12">let owner = …</text><path d="M15 70h124M15 97h124" stroke="var(--line)"/><text x="14" y="88" font-size="10">ptr    • ────────</text><text x="14" y="115" font-size="10">len    capacity</text>`:code.map((line,i)=>`<text x="11" y="51" transform="translate(0,${i*21})" font-size="8.2" fill="${i===0?'var(--rust)':'var(--muted)'}">${esc(line.length>26?line.slice(0,24)+'…':line)}</text>`).join('')}</g>
<g class="node ${active?'':'muted-node'}" transform="translate(353,105)"><path d="M0 20L70-18l78 44v107l-78 40L0 130Z" fill="var(--violet)" stroke="var(--ink)" stroke-width="1.5"/><path d="M0 20l78 44v109L0 130Z" fill="var(--sheet)" stroke="var(--ink)" stroke-width="1.5"/><path d="M78 64l70-38v107l-70 40Z" fill="var(--violet)" stroke="var(--ink)" stroke-width="1.5"/><g transform="translate(13,50)"><path d="M0 0l50 29v18L0 18Z" fill="var(--orange)" stroke="var(--line)"/><path d="M0 32l50 29v18L0 50Z" fill="var(--green)" stroke="var(--line)"/><path d="M0 64l50 29v18L0 82Z" fill="var(--violet)" stroke="var(--line)"/></g><g transform="translate(88,79)"><circle cx="4" cy="0" r="3" fill="#8fa762"/><circle cx="20" cy="-9" r="3" fill="#8fa762"/><circle cx="36" cy="-18" r="3" fill="#d89b75"/></g><text x="115" y="105" text-anchor="middle" font-size="11" transform="rotate(-28 115 105)">${memory?'HEAP':'RUST'}</text></g>
<g class="node ${out?'':'muted-node'}" transform="translate(617,112)"><rect x="5" y="5" width="148" height="133" rx="6" fill="var(--line)" stroke="var(--ink)"/><rect width="148" height="133" rx="6" fill="var(--sheet)" stroke="var(--ink)" stroke-width="1.5"/><path d="M1 6q0-5 5-5h136q5 0 5 5v22H1Z" fill="var(--green)"/><text x="12" y="18" font-size="10">${memory?'reference view':'a useful result'}</text>${[0,1,2].map((n)=>`<rect x="12" y="${43+n*27}" width="12" height="12" rx="3" fill="${out?'var(--green)':'var(--card)'}" stroke="var(--line)"/>${out?`<path d="M15 ${49+n*27}l3 3 5-6" fill="none" stroke="#6d8949" stroke-width="1.5"/>`:''}<path d="M34 ${49+n*27}h${[91,70,81][n]}" stroke="var(--line)" stroke-width="4"/>`).join('')}</g>
${[165,425,690].map((cx,i)=>`<text x="${cx}" y="326" text-anchor="middle" font-size="12" font-weight="600">${esc(flow[i])}</text><text x="${cx}" y="348" text-anchor="middle" class="muted-text" font-size="10">${esc(flow[i+3])}</text>`).join('')}${active?`<circle cx="230" cy="238" r="4" fill="#d99a72" stroke="var(--ink)"><animateMotion dur="3s" repeatCount="indefinite" path="M0 0L80 47L195 -20"/></circle><circle cx="480" cy="238" r="4" fill="#a8bd83" stroke="var(--ink)"><animateMotion dur="3.6s" repeatCount="indefinite" path="M0 0L85 47L210 -20"/></circle>`:''}</svg>`;}
export function concept(l,s,x){return `<div class="concept-card"><span class="concept-label">${esc(l.module.title)} / Key idea</span><h2>${esc(s.title)}</h2><p>${esc(s.callout)}</p><div class="concept-flow">${x.flow.slice(0,3).map((t,i)=>`<span style="background:var(--${['orange','violet','green'][i]})">${esc(t)}</span>`).join('')}</div><span class="mini-stat">A conceptual map. Explore concrete values and compiler-checked examples in Rust Lab.</span></div>`;}
